            ["node.mage.frost.t2_3"]=(new[]{"Zwiększa obrażenia Sopla Lodu do 135% ataku.","Zwiększa obrażenia Sopla Lodu do 145% ataku.","Zwiększa obrażenia Sopla Lodu do 160% ataku."},"Zmienia bazowy mnożnik bezpośrednich obrażeń Sopla Lodu. Nie wzmacnia krwawienia Ostrego Sopla ani innych zaklęć."),
            ["node.mage.frost.t2_4"]=(new[]{"Sopel Lodu zamraża na 3 tury."},"Dotyczy tylko zamrożenia nałożonego przez Sopel Lodu. Odporność i tolerancja na kontrolę nadal obowiązują."),
