            ["node.mage.frost.t3_2"]=(new[]{"Soplowa Tarcza Awaryjna uruchamia się po utracie 15% maksymalnego zdrowia."},"Zmienia wyłącznie próg faktycznej utraty zdrowia Soplowej Tarczy Awaryjnej na 15% maksymalnego zdrowia."),
            ["node.mage.frost.t3_3"]=(new[]{"Aura Mrozu trwa 5 tur odbiorcy."},"Wydłuża czas premii uniku i pulsowania Aury Mrozu do 5 tur odbiorcy, także przy rzuceniu na siebie."),
