            ["node.mage.frost.t4_1"]=(new[]{"Soplowa Tarcza Awaryjna zwiększa obie obrony o 40%.","Soplowa Tarcza Awaryjna zwiększa obie obrony o 50%."},"Zwiększa premię obu obron wyłącznie podczas istnienia warstwy Soplowej Tarczy Awaryjnej. Kara po jej rozbiciu pozostaje równa −30%."),
            ["node.mage.frost.t4_2"]=(new[]{"Skraca odnowienie Soplowej Tarczy Awaryjnej do 9 tur.","Skraca odnowienie Soplowej Tarczy Awaryjnej do 8 tur.","Skraca odnowienie Soplowej Tarczy Awaryjnej do 7 tur."},"Odnowienie liczy własne tury i rozpoczyna się po udanym utworzeniu tarczy. Nie zmienia jej progu ani wartości."),
